import{_ as t,o as a,c as _,a4 as s}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"第二十三届中国国际农产品交易会筹备工作全面启动2026-06-09","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"第二十三届中国国际农产品交易会筹备工作全面启动2026-06-09","date":"2026-06-09T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202606/t20260617_6485061.htm","summary":"农民日报全媒体记者　孙莹\\n近日,农交会组委会办公室向各省区市农业农村部门和相关单位通报农交会筹备进展情况,加快推进第二十三届农交会筹备工作。\\n本届农交会由农业农村部主办,全国农业展览馆、浙江省农业农村厅、杭州市人民政府共同承办,将于11月13-16日在杭州举办,海峡两岸现代农业博览会、浙江农业博览会同期同地举办。...\\n","contentHash":"c2d6c864344a89e145e0ad3c87597fa6","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-06-09-第二十三届中国国际农产品交易会筹备工作全面启动.md","filePath":"policies/2026-06-09-第二十三届中国国际农产品交易会筹备工作全面启动.md"}'),r={name:"policies/2026-06-09-第二十三届中国国际农产品交易会筹备工作全面启动.md"};function o(n,e,c,l,p,i){return a(),_("div",null,[...e[0]||(e[0]=[s('<h1 id="第二十三届中国国际农产品交易会筹备工作全面启动2026-06-09" tabindex="-1">第二十三届中国国际农产品交易会筹备工作全面启动2026-06-09 <a class="header-anchor" href="#第二十三届中国国际农产品交易会筹备工作全面启动2026-06-09" aria-label="Permalink to &quot;第二十三届中国国际农产品交易会筹备工作全面启动2026-06-09&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202606/t20260617_6485061.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-06-09 摘要: 农民日报全媒体记者　孙莹 近日,农交会组委会办公室向各省区市农业农村部门和相关单位通报农交会筹备进展情况,加快推进第二十三届农交会筹备工作。 本届农交会由农业农村部主办,全国农业展览馆、浙江省农业农村厅、杭州市人民政府共同承办,将于11月13-16日在杭州举办,海峡两岸现代农业博览会、浙江农业博览会同期同地举办。...</p></blockquote><p>近日,农交会组委会办公室向各省区市农业农村部门和相关单位通报农交会筹备进展情况,加快推进第二十三届农交会筹备工作。</p><p>本届农交会由农业农村部主办,全国农业展览馆、浙江省农业农村厅、杭州市人民政府共同承办,将于11月13-16日在杭州举办,海峡两岸现代农业博览会、浙江农业博览会同期同地举办。本届农交会坚持“展示成果、推动交流、促进贸易”办展宗旨,以“把农业建成现代化大产业”为主题,聚焦“科技农业、绿色农业、质量农业、品牌农业”,设置农业精品品牌、海峡两岸现代农业、“人工智能+”农业、国际合作、新品创意和休闲食品等12个展区,举办强农论坛、全国采购商联盟渠道对接、品牌之夜、帮扶产业对接、新品首秀发布等重点活动,展览总面积超12万平方米。</p><p>下一步,农交会将重点抓好4方面工作。一是强化多展协同,整合中国国际农产品交易会、海峡两岸现代农业博览会、浙江农业博览会资源,实现优势互补、商机共享、影响更广。二是提升帮扶实效,集中展示特色产业培育成果和带农增收效果。三是强化专业服务,开展精准邀约,完善大型采购商名录,通过组织采购商专场、大买家对接等形式,促进供采对接。四是创新宣传推广,举办招商路演推介、“农交会走进产地行”等宣传活动,组织达人探展、网红带货、短视频传播等活动,全方位提升农交会影响力知名度。</p><p><a href="https://scs.moa.gov.cn/gzdt/202606/t20260617_6485061.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',6)])])}const m=t(r,[["render",o]]);export{f as __pageData,m as default};
